package com.bankorganiser;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(BankOrganiserConfig.GROUP)
public interface BankOrganiserConfig extends Config
{
	String GROUP = "bankorganiser";

	@ConfigSection(
		name = "Import / Export",
		description = "Share your configuration as a single string.",
		position = 10,
		closedByDefault = true
	)
	String importExportSection = "importExport";

	@ConfigItem(
		keyName = "playSound",
		name = "Play toggle sound",
		description = "Play a click sound when toggling the organised view.",
		position = 1
	)
	default boolean playSound()
	{
		return true;
	}

	@ConfigItem(
		keyName = "categoryOverrides",
		name = "Category overrides",
		description = "Force items into a category of your choice. One rule per line, as"
			+ " match=Category.\n"
			+ "'match' is part of an item name (case-insensitive), an exact item id, or a"
			+ " /regex/ pattern (wrapped in slashes, case-insensitive).\n"
			+ "A category name that isn't a built-in one creates a new section (shown at the"
			+ " top). Earlier lines win.\n"
			+ "Example:\n"
			+ "pickaxe=Mining\n"
			+ "/\\w* rune/=Runes\n"
			+ "995=Currency",
		position = 2
	)
	default String categoryOverrides()
	{
		return "";
	}

	@ConfigItem(
		keyName = "loadouts",
		name = "Loadouts",
		description = "Custom loadout sections shown at the top of the bank, with the exact"
			+ " items + quantities you need as placeholders (greyed if you're missing them),"
			+ " like Quest Helper. These do NOT remove items from the normal categories.\n"
			+ "Start each loadout with [Name], then one item per line as: optional quantity,"
			+ " then an item name (or id:1234). Blank/# lines are ignored.\n"
			+ "Example:\n"
			+ "[Herb Farming Run]\n"
			+ "Ectophial\n"
			+ "4 Law rune\n"
			+ "14 Air rune\n"
			+ "1 Earth rune\n"
			+ "1 Water rune\n"
			+ "Dramen staff",
		position = 3
	)
	default String loadouts()
	{
		return "";
	}

	@ConfigItem(
		keyName = "categoryOrder",
		name = "Category order",
		description = "Reorder the category sections. List section names one per line, top to"
			+ " bottom; any you don't list keep their default order below. Names are"
			+ " case-insensitive and match the built-in categories or your custom override"
			+ " sections.\n"
			+ "Built-in: Melee Equipment, Ranged Equipment, Mage Equipment, Runecrafting,"
			+ " Mining & Smithing, Woodcutting, Fishing, Farming, Herb Seeds, Tree Seeds, Herbs,"
			+ " Potions, Food, Teleports, Jewellery, Gems, Currency, Equipment, Resources, Other.\n"
			+ "Example:\n"
			+ "Food\n"
			+ "Potions\n"
			+ "Runecrafting",
		position = 4
	)
	default String categoryOrder()
	{
		return "";
	}

	@ConfigItem(
		keyName = "exportToClipboard",
		name = "Export to clipboard",
		description = "Flip this to copy your current Bank Assistant configuration (overrides,"
			+ " loadouts, category order, sound) to the clipboard as a shareable string. It flips"
			+ " back automatically.",
		section = importExportSection,
		position = 1
	)
	default boolean exportToClipboard()
	{
		return false;
	}

	@ConfigItem(
		keyName = "importConfig",
		name = "Import string",
		description = "Paste an exported Bank Assistant configuration string here, then flip"
			+ " 'Load imported config' below to apply it.",
		section = importExportSection,
		position = 2
	)
	default String importConfig()
	{
		return "";
	}

	@ConfigItem(
		keyName = "loadImportedConfig",
		name = "Load imported config",
		description = "Flip this to apply the configuration string in 'Import string' above."
			+ " It overwrites your overrides, loadouts, category order and sound, then flips back.",
		section = importExportSection,
		position = 3
	)
	default boolean loadImportedConfig()
	{
		return false;
	}
}

